import "core-js/modules/es6.array.find";
import { getDictList } from '@/api/dict';
import { getDataById } from "@/api/xcnanr/visitationConfig";
import Breadcrumb from "../../components/Breadcrumb";
export default {
  components: {
    Breadcrumb: Breadcrumb
  },
  data: function data() {
    return {
      dictForVisitationType: [],
      dictForEnableStatus: [],
      form: {
        name: '',
        type: '1',
        roomId: '',
        roomName: '',
        detailList: []
      },
      detailTableKey: 0
    };
  },
  props: {
    dialogFlag: {
      type: Boolean,
      default: false
    },
    dialogObject: {
      type: Object,
      default: null
    }
  },
  created: function created() {
    var _this2 = this;
    // 加载字典信息：巡视类型
    getDictList("info_inspection_plan_type").then(function (res) {
      _this2.dictForVisitationType = res.data;
    });
    // 加载字典信息：启用状态
    getDictList("info_enable_status").then(function (res) {
      _this2.dictForEnableStatus = res.data;
    });
    this.initForm();
  },
  methods: {
    // 关闭当前弹层
    closeThisDialog: function closeThisDialog() {
      this.$emit('closeDialog', null);
    },
    convertDictValue: function convertDictValue(type, dictList) {
      var item = dictList.find(function (config) {
        return config.dictKey === type;
      });
      return item ? item.dictValue : null;
    },
    initForm: function initForm() {
      var configId = this.dialogObject.id;
      var _this = this;
      getDataById(configId).then(function (res) {
        if (res && res.code === 200) {
          _this.form = res['data'];
          _this.form.type = _this.form.type += '';
          _this.detailTableKey += 1;
        }
      });
    }
  }
};
